export type GamepadSvgColors = Partial<typeof DEFAULTS>

// Shared stroke props (reused by most elements)
function stroked(c: Required<typeof DEFAULTS>) {
  return {
    stroke: c.strokeColor,
    'stroke-width': c.strokeWidth,
    'stroke-linecap': 'butt',
    'stroke-linejoin': 'miter',
    'stroke-miterlimit': '10',
    'stroke-opacity': '1',
  } as Record<string, string>
}

// Common fill props
function filled(fill: string) {
  return {
    fill,
    'fill-opacity': '1',
    'fill-rule': 'evenodd',
    opacity: '1',
  } as Record<string, string>
}

