/*#
# dialog

`<tosi-dialog>` is a simple wrapper around the standard HTML `<dialog>` element designed
to make creating dialogs as convenient as possible.

```html
<button>Show Dialog</button>
<tosi-dialog>
  <h3 slot='header'>A Dialog</h3>
  <p>
    Here is some text
  </p>
  <button slot="footer">Custom Button</button>
</tosi-dialog>
```
```js
import { on } from 'tosijs'
import { postNotification } from 'tosijs-ui'

on(
  preview.querySelector('button'),
  'click',
  async () => {
    const response = await preview.querySelector('tosi-dialog').showModal()
    postNotification({
      message: `user clicked ${response}`,
      duration: 2
    })
  }
)
```
```test
const dialog = preview.querySelector('tosi-dialog')
test('dialog renders', () => {
  expect(dialog).toBeTruthy()
  expect(dialog.tagName.toLowerCase()).toBe('tosi-dialog')
})
test('dialog has header slot content', () => {
  const header = dialog.querySelector('[slot="header"]')
  expect(header).toBeTruthy()
  expect(header.textContent).toBe('A Dialog')
})
```

The dialog always supplies its own **OK** button (`part="ok"`, which closes with
`'confirm'`). Buttons you put in the `footer` slot appear **beside** it, not instead of it, so
add a Cancel button there, not a second OK.

## Closing

Every way a dialog closes — the OK button, `close(reason)`, a background click when
`closeOnBackgroundClick` is set, **Escape**, or a `<form method="dialog">` — goes through the
same path: `dialogWillClose(reason)` is called, the `showModal()` promise resolves with the
reason, and a `removeOnClose` dialog removes itself. Escape closes with `'cancel'`.

`dialogWillClose` can **refuse** a close by returning `false`, or a Promise resolving to
`false`. Use it for a dialog that must not be dismissed while it is busy, such as an async save
in flight. `close()` returns whether the dialog closed, or a Promise of that when
`dialogWillClose` is async.

```typescript
const editor = tosiDialog({
  dialogWillClose: () => !saving, // Escape and Cancel do nothing mid-save
})
```

The browser can close a `<dialog>` without asking (a `<form method="dialog">` submission, or a
repeated Escape without fresh user interaction in Chrome). Those cannot be refused; the dialog
still calls `dialogWillClose` and resolves, so nothing waits forever.

## Static Functions

`TosiDialog` provides static async functions to replace the built-in dialogs provided by
the browser.

- `alert(message: string, title = 'Alert'): Promise<undefined>`
- `confirm(message: string, title = 'Confirm'): Promise<boolean>`
- `prompt(message: string, title = 'Prompt', currentValue = ''): Promise<string | null> `

You can look at the code that implements them to see how to leverage `TosiDialog` to build
more complex, bespoke dialogs that can be used just as conveniently.

```js
import { elements } from 'tosijs'
import { TosiDialog, postNotification } from 'tosijs-ui'

const { button, div } = elements

preview.append(
  div(
    {
      style: {
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'flex-start',
        gap: 10
      }
    },
    button(
      {
        async onClick() {
          await TosiDialog.alert('This is an alert')
          postNotification({
            message: 'alert dismissed',
            duration: 2
          })
        }
      },
      'TosiDialog.alert',
    ),
    button(
      {
        async onClick() {
          const confirmed = await TosiDialog.confirm('Can you confirm?')
          postNotification({
            message: `user ${confirmed ? 'confirmed' : 'cancelled'}`,
            duration: 2
          })
        }
      },
      'TosiDialog.confirm',
    ),
    button(
      {
        async onClick() {
          const text = await TosiDialog.prompt('Enter some text please')
          postNotification({
            message: text !== null ? `user entered "${text}"`: 'user cancelled',
            duration: 2
          })
        }
      },
      'TosiDialog.prompt',
    ),
  ),
)
```
```css
.preview {
  padding: 10px;
}
```

*/
/*{ "parent": "Components" }*/
import { Component, elements, on, vars, varDefault } from 'tosijs';
import { findHighestZ } from './track-drag.js';
const { dialog, button, header, footer, tosiSlot, h3, p, label, input, div } = elements;
export class TosiDialog extends Component {
    static preferredTagName = 'tosi-dialog';
    static lightStyleSpec = {
        ':host > dialog::backdrop': {
            backdropFilter: 'blur(8px)',
        },
        ':host > dialog:not([open])': {
            display: 'none',
        },
        ':host > dialog[open]': {
            minWidth: 300,
            border: 0,
            borderRadius: 10,
            overflow: 'hidden',
            maxHeight: 'calc(100% - 20px)',
            padding: 0,
            display: 'flex',
            flexDirection: 'column',
            gap: 5,
            _dialogShadow: varDefault.menuShadow('0 5px 10px #0004'),
            _dialogBackground: varDefault.background('#fafafa'),
            _dialogColor: varDefault.textColor('#222'),
            boxShadow: vars.dialogShadow,
            background: vars.dialogBackground,
            color: vars.dialogColor,
        },
        ':host > dialog > *': {
            padding: '0 20px',
        },
        ':host > dialog > header': {
            display: 'flex',
            justifyContent: 'center',
            gap: 10,
        },
        ':host > dialog > footer': {
            display: 'flex',
            justifyContent: 'flex-end',
            gap: 10,
            paddingBottom: 20,
        },
    };
    static async alert(message, title = 'Alert') {
        return new Promise((resolve) => {
            const alertDialog = tosiDialog({
                removeOnClose: true,
                closeOnBackgroundClick: true,
                dialogWillClose() {
                    resolve();
                },
            }, h3({ slot: 'header' }, title), message.includes('\n')
                ? elements.pre({ style: { whiteSpace: 'pre-wrap', margin: 0 } }, message)
                : p(message));
            document.body.append(alertDialog);
            alertDialog.showModal();
        });
    }
    static async confirm(message, title = 'Confirm') {
        return new Promise((resolve) => {
            const confirmDialog = tosiDialog({
                removeOnClose: true,
                dialogWillClose(reason) {
                    resolve(reason === 'confirm');
                },
            }, h3({ slot: 'header' }, title), p(message), button({
                slot: 'footer',
                onClick() {
                    confirmDialog.close();
                },
            }, 'Cancel'));
            document.body.append(confirmDialog);
            confirmDialog.showModal();
        });
    }
    static async prompt(message, title = 'Prompt', currentValue = '') {
        return new Promise((resolve) => {
            const inputField = input({ value: currentValue });
            const promptDialog = tosiDialog({
                removeOnClose: true,
                dialogWillClose(reason) {
                    resolve(reason === 'confirm' ? inputField.value : null);
                },
                initialFocus() {
                    inputField.focus();
                },
            }, h3({ slot: 'header' }, title), p(label({
                style: {
                    display: 'flex',
                    flexDirection: 'column',
                    alignItems: 'stretch',
                    gap: 5,
                },
            }, div(message), inputField)), button({
                slot: 'footer',
                onClick() {
                    promptDialog.close();
                },
            }, 'Cancel'));
            document.body.append(promptDialog);
            promptDialog.showModal();
        });
    }
    removeOnClose = false;
    closeOnBackgroundClick = false;
    constructor() {
        super();
        on(this, 'click', () => {
            if (this.closeOnBackgroundClick) {
                this.close();
            }
        });
    }
    /**
    Called before the dialog closes, with the reason (`'confirm'`, `'cancel'`, or whatever was
    passed to `close()`). Return `false` — or a Promise resolving to `false` — to refuse the
    close, e.g. while an async save is in flight: a dialog that cannot be cancelled must not
    look as though it was.
    */
    dialogWillClose = (_reason = 'cancel') => {
        /* override to observe or veto */
    };
    initialFocus() {
        this.parts.ok.focus();
    }
    #modalResolution = (_outcome) => {
        /* noop */
    };
    /*
    True once this showing's close side effects have run — resolution, removal — so that no path
    runs them twice. Every route to "closed" funnels into #finish, and there are three: close()
    (buttons, background click, callers), Escape (the native `cancel`), and the browser closing
    the element on its own (the native `close` event, below).
    */
    #settled = false;
    showModal = () => {
        this.style.zIndex = String(findHighestZ());
        this.#settled = false;
        return new Promise((resolve) => {
            this.#modalResolution = resolve;
            this.parts.dialog.showModal();
            requestAnimationFrame(() => {
                this.initialFocus();
            });
        });
    };
    /**
    Close the dialog unless `dialogWillClose` vetoes it. Returns whether it closed — a Promise
    of that when `dialogWillClose` is async.
    */
    close = (reason = 'cancel') => {
        if (this.#settled) {
            return true;
        }
        const verdict = this.dialogWillClose(reason);
        if (verdict instanceof Promise) {
            return verdict.then((v) => (v === false ? false : this.#finish(reason)));
        }
        return verdict === false ? false : this.#finish(reason);
    };
    #finish(reason) {
        if (this.#settled) {
            return true;
        }
        this.#settled = true;
        this.#modalResolution(reason);
        if (this.parts.dialog.open) {
            this.parts.dialog.close();
        }
        if (this.removeOnClose) {
            this.remove();
        }
        return true;
    }
    /*
    Escape (#183). The browser would close the <dialog> itself and bypass close(), so the static
    helpers never resolved and removeOnClose leaked the element. Take the close over instead,
    which is also what lets dialogWillClose veto it.
    */
    onCancel = (event) => {
        event.preventDefault();
        this.close('cancel');
    };
    /*
    The browser can still close the element without asking: Chrome's close-watcher makes a repeat
    `cancel` non-cancelable without fresh user activation, and `<form method="dialog">` closes it
    directly. Too late to veto, so tell dialogWillClose and settle, rather than hang the caller.
    */
    onNativeClose = () => {
        if (this.#settled) {
            return;
        }
        const reason = this.parts.dialog.returnValue || 'cancel';
        this.dialogWillClose(reason);
        this.#finish(reason);
    };
    ok = () => {
        this.close('confirm');
    };
    content = () => dialog({ part: 'dialog', onCancel: this.onCancel, onClose: this.onNativeClose }, header(tosiSlot({ name: 'header' })), tosiSlot(), footer(tosiSlot({ name: 'footer' }), button({ part: 'ok', onClick: this.ok }, 'OK')));
}
export const tosiDialog = TosiDialog.elementCreator();
